cat > /private/tmp/100-tricks-runs/d12/without/h2-eval-thresholds/r3/test-thresholds.js << 'EOF'
// Quick test of threshold functionality
import { Eval } from './packages/frai-core/src/index.js';

// Test 1: Basic threshold passing
console.log('Test 1: Thresholds that pass');
const evals1 = Eval.runEvaluations({
  outputs: ['a', 'b', 'c'],
  references: ['a', 'b', 'c']
});
const report1 = Eval.generateReport({
  evaluations: evals1,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 0.5 }
});
console.log('✓ Report includes passed:', report1.passed === true);
console.log('✓ Threshold passed:', report1.thresholds[0].passed === true);

// Test 2: Threshold failing
console.log('\nTest 2: Thresholds that fail');
const evals2 = Eval.runEvaluations({
  outputs: ['a', 'b', 'c'],
  references: ['a', 'x', 'c']
});
const report2 = Eval.generateReport({
  evaluations: evals2,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 0.95 }
});
console.log('✓ Report includes passed:', report2.passed === false);
console.log('✓ Threshold failed:', report2.thresholds[0].passed === false);

// Test 3: Threshold with null score
console.log('\nTest 3: Threshold with null score');
const evals3 = Eval.runEvaluations({
  outputs: ['a', 'b', 'c']
  // no references
});
const report3 = Eval.generateReport({
  evaluations: evals3,
  outputsPath: '/tmp/out.json',
  referencesPath: null,
  thresholds: { exact_match: 0.5 }
});
console.log('✓ Threshold with null score fails:', report3.thresholds[0].passed === false);

// Test 4: Multiple thresholds
console.log('\nTest 4: Multiple thresholds, mixed pass/fail');
const evals4 = Eval.runEvaluations({
  outputs: ['a', 'b'],
  references: ['a', 'b']
});
const report4 = Eval.generateReport({
  evaluations: evals4,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 0.5, toxicity: 0.5 }
});
console.log('✓ Multiple thresholds recorded:', report4.thresholds.length === 2);
console.log('✓ Overall passed is false due to toxicity fail:', report4.passed === false);

// Test 5: No thresholds (backward compat)
console.log('\nTest 5: No thresholds (backward compatibility)');
const evals5 = Eval.runEvaluations({
  outputs: ['a'],
  references: ['a']
});
const report5 = Eval.generateReport({
  evaluations: evals5,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json'
});
console.log('✓ No passed field:', report5.passed === undefined);
console.log('✓ No thresholds array:', report5.thresholds === undefined);

console.log('\n✅ All tests passed!');
EOF
node test-thresholds.js
